/**
 * Retorna las entidades CMI vigentes: si el usuario cargó un archivo CMI
 * personalizado, se usa prioritariamente; de lo contrario se usa la verdad de código.
 */
export function obtenerEntidadesCMIActivas(): Record<string, CMIEntity> {
  const personalizada = obtenerMatrizCMIPersonalizada();
  return personalizada && Object.keys(personalizada).length > 0 ? personalizada : CMI_ENTITIES;
}
